// 社长室 · 动态加载器（卡版本 0.1.20）
// 本体托管在公开仓库 github.com/fannnnnnn5822/voice-agency-card 的 dist/shacho.js，走 jsDelivr；版本指针在 Supabase ac_config.shacho_script_ref
// @提交号是不可变路径，绕开 CDN 缓存；指针没有 → 拉 @v0.1.20（这张卡发版时的 tag，同样不可变），不退 @main；卡里不带备份
(async function () {
  var L = function (m) { try { console.log('[社长室 loader] ' + m); } catch (e) {} };
  var ref = '', code = null, how = '', off = '';
  try {
    var c0 = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    var t0 = c0 ? setTimeout(function () { c0.abort(); }, 6000) : null;
    var r0 = await fetch('https://hieylivlsdmyznviumht.supabase.co/rest/v1/ac_config?key=in.(shacho_script_ref,shacho_card_version,shacho_off)&select=key,value', { cache: 'no-store', signal: c0 ? c0.signal : undefined,
      headers: { 'apikey': 'sb_publishable_MH80Xnlm1oHli6UXwzRpNA_EsC1DnCO', 'Authorization': 'Bearer sb_publishable_MH80Xnlm1oHli6UXwzRpNA_EsC1DnCO' } });
    if (t0) clearTimeout(t0);
    if (r0.ok) {
      var rows = await r0.json();
      (rows || []).forEach(function (row) {
        var v = String((row && row.value) || '').trim();
        if (row && row.key === 'shacho_script_ref' && /^[A-Za-z0-9._-]{4,60}$/.test(v)) ref = v;
        if (row && row.key === 'shacho_off' && v) off = v;
        if (row && row.key === 'shacho_card_version' && v && v !== '0.1.20') L('整卡有新版 ' + v + '（这张是 0.1.20），快捷回复栏会出现「更新角色卡」按钮');
      });
      if (!ref) L('指针里还没有可用的提交号');
    } else L('指针 HTTP ' + r0.status);
  } catch (e0) { L('指针请求失败：' + ((e0 && e0.message) || e0)); }
  if (off) { L('作者关了社长室：' + off); try { toastr.info(off, '🚪 社长室', { timeOut: 0, extendedTimeOut: 0 }); } catch (e6) {} return; }
  var refs = ref ? [ref, 'v0.1.20'] : ['v0.1.20'];
  var hosts = ["testingcf.jsdelivr.net", "fastly.jsdelivr.net", "cdn.jsdelivr.net"];
  for (var k = 0; k < refs.length && code == null; k++) {
    for (var i = 0; i < hosts.length && code == null; i++) {
      var url = 'https://' + hosts[i] + '/gh/fannnnnnn5822/voice-agency-card@' + refs[k] + '/dist/shacho.js';
      try {
        var c1 = (typeof AbortController !== 'undefined') ? new AbortController() : null;
        var t1 = c1 ? setTimeout(function () { c1.abort(); }, 12000) : null;
        var r1 = await fetch(url, { cache: 'no-store', signal: c1 ? c1.signal : undefined });
        if (t1) clearTimeout(t1);
        if (!r1.ok) throw new Error('HTTP ' + r1.status);
        var txt = await r1.text();
        if (!txt || txt.length < 50000 || txt.indexOf('SHACHO_LISTS') < 0) throw new Error('内容不像社长室（' + (txt ? txt.length : 0) + ' 字）');
        code = txt; how = '@' + refs[k].slice(0, 7) + ' via ' + hosts[i];
      } catch (e1) { L('源 ' + hosts[i] + ' 失败：' + ((e1 && e1.message) || e1)); }
    }
  }
  if (code == null) { try { toastr.error('社长室没连上网：脚本要从 jsDelivr 下载，网络通了刷新一下就好。', '🚪 社长室', { timeOut: 15000 }); } catch (e5) {} return; }
  L('用的是' + how + '（' + code.length + ' 字）');
  try { eval(code); } catch (e2) {
    try { toastr.error('社长室启动出错：' + ((e2 && e2.message) || e2), '🚪 社长室'); } catch (e4) {}
  }
})();
